import{_ as t,c as i,o as s,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"易緯辨終備〔漢〕鄭玄","description":"易緯辨終備 - 易緯辨終備〔漢〕鄭玄","frontmatter":{"title":"易緯辨終備〔漢〕鄭玄","description":"易緯辨終備 - 易緯辨終備〔漢〕鄭玄"},"headers":[],"relativePath":"classics/yiwei-bianzhongbei/001.md","filePath":"classics/yiwei-bianzhongbei/001.md"}'),r={name:"classics/yiwei-bianzhongbei/001.md"};function o(c,a,l,d,p,m){return s(),i("div",null,[...a[0]||(a[0]=[e("h1",{id:"易緯辨終備〔漢〕鄭玄",tabindex:"-1"},[n("易緯辨終備〔漢〕鄭玄 "),e("a",{class:"header-anchor",href:"#易緯辨終備〔漢〕鄭玄","aria-label":"Permalink to “易緯辨終備〔漢〕鄭玄”"},"​")],-1),e("p",null,"欽定四庫全書易緯辨終備 ​漢 鄭康成 注孔子表河圖皇參持曰：天以鬥視，日發明，皇以戲招始，掛八卦談。 ​皇參持，河圖名也。言以北斗之星視聽，而以日月發其明，以昭示天地。三皇伏戲始卦，以示後世之人，謂使觀見之矣。煌煌之燿，乾為之岡。合凝之類，坤握其方。 ​煌煌，光輝之貌。燿，日月五星也。皆以乾岡圖言，盡繫於天也。方，道也。合凝，為首形之類，坤則握其道，皆繫於地也。雄雌呿吟，六節搖通。 ​雄雌，天地。呿吟，闔閉也。六節，六子也。搖通，言六子動行天地之氣。系曰：「閉戶謂之坤，闢戶謂之乾。」又曰：天地定位，山澤通氣也。萬物孳甲，曰營始東。 ​孳，生也。甲，東方之行，物所生，故數以始也。三五環復，七十六載閏反常。 ​三五千百二十歲，歷歷復其本，七十六載則餘分盡。言天終則後始者耳也。旋出樞，乾機據參衡出坤，離，授提巽招震夘， ​乾正。旋、樞、衡、招皆北星，值乾君之象。旋星出樞之政教。機，正，機之發動，故其位據。參，西方之宿。五事五方為言，猶君出政之言也。玉衡之星，言主布天之手法，於坤離授明，提巽招震之職權，君平事之臣。夘，東方之宿也。○按五事五方與正文不相應，疑有脫文。緯嬴縮，辰中效當。 ​緯，五緯。盈縮，行有進退也。辰，星。仲，謂夘酉子午。候星辰之常，以四仲之月視其效當與不也。必視熒惑所在時殃。 ​熒惑主理天下，故必候之，以知時禍。循歲德，鎮之光。 ​鎮主章存德，故候星之光，以故德之所在也。拒白甄商，金大謀兵。 ​拒白，太白之主殺罰，而金宿，故甄商金聲，言太白大為眾之候，元武兵大謀之也。雪霜，水疾，旱飢，喪，地動，山崩淪，慧隕，物吝悖淫。 ​崩淪，若步庶崩者也。慧，彗。隕，隕石也，立社稷之類。悖，見。淫，散也。負之傍害，水決，江德潰，河空移徙，赤黃。 ​負之示聞。傍，水決貌。江德潰，亦謂決亂而出也。空，竭之。移徙，地震之類也。踴起，物怪踴躍出見，以日昴衝望之，曰乘陰氣。○按「示聞」二字疑誤，「踴起」以下與正文不相應，疑有脫文。箕風飄石折，拔樹酷深。 ​酷，暴也。飄石折樹，言繋夾也。暴深，害物甚也。長大卒嬉，暴大楊。 ​暴大，言不以漸。楊楊，大貌也。解裂珥偶，虹霓孽行。 ​解，陷也，淪也。裂，地圯。珥偶、虹霓，皆日傍氣名妖。沉藏相桐，水害□滂滂。 ​沉藏，當藏以物。相，當為桐。射發立也。滂滂，水貌也。日之既，陽德消。月之毀，刑將將。 ​日既，日蝕，明盡，故陽消。月之毀，亦謂月蝕常過也。陰將，將，大也。陰主刑，陰似脫之大怪。土蒙，群鳥卻，野獸群，遊人孳。 ​來濟者，來成也。其氣不效，君不能修德杜漸防萌。黃霧滿者，亂氣起也。朝方陽，埃寇將來，十刃之，莫四出，虻牛招屍，益士與之開。皆離坎之異也。鱗出者，聖人將起，授之符緯。有王者則聚生五帝之坐。其帝將王，則其坐亡光也。○按此注皆與正文不相合，疑有脫簡。按錄視天，比象由。 ​按錄，按河圖之錄，又視按王光之異，比其象以觀其光由，起也。神靈悉存，八八通時， ​在，察也。神靈，三光異及符瑞也。既按三光之異及符瑞，以知起者所由，以六十四卦通，其謂以何？○按正文無「在」字，而注言「在，察也」，亦疑有脫文。小辨終備，無遺戒。郄知億，察世郵。 ​世郵，郄變也。帝王奉命，永安治。 ​命，猶書也。至哉易，三聖謀，專密惡，必孰思。 ​三聖：伏羲、文王、孔子。○按史記張守節正義引易中備雲：「孔子正月為商瞿筮，曰：瞿當有五丈夫子。子貢曰：何以知之？子曰：卦遇大畜，艮之二世，九二甲寅木為世，九五景子水為應，陽爻五，應有五子云雲。」檢今書無其文，蓋非全本也。自伏羲以來，漢永和元年，凡四十萬九千三百八十九歲。 ​按：此為後人所加，非易緯本文。",-1)])])}const h=t(r,[["render",o]]);export{f as __pageData,h as default};
